// From 'pg', the runtime package — never '@types/pg' (see db.ts).
import { Pool } from 'pg';
import type { FastifyBaseLogger } from 'fastify';

/**
 * Persisted markdown reports generated by the Site Report Generator (see
 * app/agent/report_generator.py). Same enabled/no-op-fallback shape as
 * db.ts's Repository, kept as its own store since a site can accumulate a
 * history of generated reports over time, distinct from any one inversion
 * result.
 */
export interface SiteReport {
  siteId: string;
  markdown: string;
  summary: string;
  createdAt: number;
}

export interface SiteReportStore {
  readonly enabled: boolean;
  init(): Promise<void>;
  save(report: SiteReport): Promise<void>;
  listBySite(siteId: string, limit: number): Promise<SiteReport[]>;
  close(): Promise<void>;
}

const SCHEMA = `
CREATE TABLE IF NOT EXISTS site_reports (
  id          SERIAL PRIMARY KEY,
  site_id     TEXT NOT NULL,
  markdown    TEXT NOT NULL,
  summary     TEXT NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_site_reports_site_id_created_at
  ON site_reports (site_id, created_at DESC);
`;

const delay = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function rowToReport(row: any): SiteReport {
  return {
    siteId: row.site_id,
    markdown: row.markdown,
    summary: row.summary,
    createdAt: new Date(row.created_at).getTime(),
  };
}

class PostgresSiteReportStore implements SiteReportStore {
  readonly enabled = true;
  private readonly pool: Pool;

  constructor(connectionString: string, private readonly logger: FastifyBaseLogger) {
    this.pool = new Pool({ connectionString, max: 2 });
    this.pool.on('error', (err) => this.logger.error({ err: err.message }, 'Postgres pool error (site reports)'));
  }

  async init(): Promise<void> {
    const attempts = 10;
    for (let i = 1; i <= attempts; i++) {
      try {
        await this.pool.query(SCHEMA);
        this.logger.info('Postgres site_reports schema ready');
        return;
      } catch (err) {
        if (i === attempts) throw err;
        this.logger.warn({ attempt: i }, 'Postgres not ready (site reports) — retrying');
        await delay(Math.min(1000 * i, 5000));
      }
    }
  }

  async save(report: SiteReport): Promise<void> {
    await this.pool.query(
      `INSERT INTO site_reports (site_id, markdown, summary, created_at) VALUES ($1, $2, $3, $4)`,
      [report.siteId, report.markdown, report.summary, new Date(report.createdAt).toISOString()],
    );
  }

  async listBySite(siteId: string, limit: number): Promise<SiteReport[]> {
    const { rows } = await this.pool.query(
      'SELECT * FROM site_reports WHERE site_id = $1 ORDER BY created_at DESC LIMIT $2',
      [siteId, limit],
    );
    return rows.map(rowToReport);
  }

  async close(): Promise<void> {
    await this.pool.end();
  }
}

class InMemorySiteReportStore implements SiteReportStore {
  readonly enabled = false;
  private readonly reports = new Map<string, SiteReport[]>();

  constructor(private readonly logger: FastifyBaseLogger) {}

  async init(): Promise<void> {
    this.logger.warn('DATABASE_URL not set — site reports kept in memory only (lost on restart)');
  }

  async save(report: SiteReport): Promise<void> {
    const existing = this.reports.get(report.siteId) ?? [];
    existing.unshift(report);
    this.reports.set(report.siteId, existing);
  }

  async listBySite(siteId: string, limit: number): Promise<SiteReport[]> {
    return (this.reports.get(siteId) ?? []).slice(0, limit);
  }

  async close(): Promise<void> {
    /* no-op */
  }
}

export function createSiteReportStore(
  connectionString: string | undefined,
  logger: FastifyBaseLogger,
): SiteReportStore {
  return connectionString
    ? new PostgresSiteReportStore(connectionString, logger)
    : new InMemorySiteReportStore(logger);
}
